# View ur ALONE — no MoveIt, no controllers. Use this to get familiar
# with the robot: URDF -> robot_state_publisher, joint sliders, RViz.
#
#   ros2 launch yt_ur5_robotiq_description view_robot.launch.py
#
# Generated by the TrainIt Setup Assistant.
import os

from ament_index_python.packages import get_package_share_directory
from launch import LaunchDescription
from launch.substitutions import Command
from launch_ros.actions import Node
from launch_ros.parameter_descriptions import ParameterValue


def generate_launch_description():
    share = get_package_share_directory("yt_ur5_robotiq_description")
    xacro_file = os.path.join(share, "urdf", "ur.urdf.xacro")
    # on_stderr="warn": xacro's load_yaml deprecation warning goes to stderr, and
    # Command() treats ANY stderr as a fatal error by default (launch would abort).
    robot_description = {"robot_description": ParameterValue(
        Command(["xacro ", xacro_file], on_stderr="warn"), value_type=str)}
    rviz_config = os.path.join(share, "rviz", "view_robot.rviz")
    return LaunchDescription([
        Node(package="robot_state_publisher", executable="robot_state_publisher",
             output="screen", parameters=[robot_description]),
        Node(package="joint_state_publisher_gui", executable="joint_state_publisher_gui",
             output="screen"),
        Node(package="rviz2", executable="rviz2", output="log",
             arguments=["-d", rviz_config]),
    ])
